-- ACTUALIZA LA EVALUACIÓN EXISTENTE A 30 PREGUNTAS
-- Ejecutar una sola vez en Supabase > SQL Editor.
update public.exams
set questions = '[{"q": "¿Cuál es la función principal de la energía eléctrica en un computador?", "o": ["Proporcionar la energía necesaria para que funcionen sus componentes", "Guardar permanentemente los programas", "Traducir Python a lenguaje humano", "Crear automáticamente algoritmos"], "a": 0}, {"q": "En un computador, los valores 0 y 1 representan principalmente:", "o": ["Dos programas diferentes", "Estados lógicos de señales electrónicas", "Dos tipos de memoria RAM", "Las teclas de entrada y salida"], "a": 1}, {"q": "¿Cuál secuencia describe mejor cómo una letra puede ser procesada por el computador?", "o": ["Letra → representación numérica/binaria → procesamiento → visualización", "Letra → impresora → CPU → teclado", "CPU → letra → electricidad → teclado", "RAM → teclado → letra → disco"], "a": 0}, {"q": "¿Qué dispositivo pertenece a la unidad de entrada?", "o": ["Monitor", "Impresora", "Teclado", "Parlante"], "a": 2}, {"q": "¿Cuál es la función principal de la CPU?", "o": ["Mostrar imágenes únicamente", "Ejecutar instrucciones y procesar datos", "Almacenar archivos permanentemente", "Introducir datos al computador"], "a": 1}, {"q": "¿Qué componente almacena temporalmente datos y programas que están siendo utilizados?", "o": ["RAM", "Monitor", "Teclado", "Impresora"], "a": 0}, {"q": "¿Cuál de los siguientes se utiliza normalmente para almacenamiento permanente?", "o": ["Registro de la CPU", "RAM", "SSD", "ALU"], "a": 2}, {"q": "¿Cuál es el flujo básico de las unidades funcionales del computador?", "o": ["Salida → Entrada → Proceso", "Entrada → Proceso → Salida", "Proceso → Salida → Entrada", "Almacenamiento → Entrada → Teclado"], "a": 1}, {"q": "¿Qué es un algoritmo?", "o": ["Una secuencia ordenada de pasos para resolver un problema", "Una pieza física del computador", "Un tipo de energía", "Únicamente un programa escrito en Python"], "a": 0}, {"q": "¿Qué es un programa?", "o": ["Un conjunto de instrucciones escritas para que el computador realice una tarea", "Un dispositivo de entrada", "Una memoria física", "Una señal eléctrica sin instrucciones"], "a": 0}, {"q": "Antes de programar una solución, es importante principalmente:", "o": ["Cambiar el teclado", "Comprender y analizar el problema", "Comprar más memoria RAM", "Imprimir el código"], "a": 1}, {"q": "¿Cuál relación es correcta?", "o": ["Problema → algoritmo → programa → resultado", "Resultado → problema → teclado → algoritmo", "Programa → energía → problema → monitor", "RAM → algoritmo → problema → impresora"], "a": 0}, {"q": "En el ciclo de desarrollo de software, la etapa de análisis busca:", "o": ["Comprender necesidades y requisitos del problema", "Eliminar todos los programas", "Cambiar componentes físicos", "Publicar sin realizar pruebas"], "a": 0}, {"q": "¿En qué etapa del desarrollo se escribe el código del programa?", "o": ["Análisis", "Diseño", "Programación o implementación del código", "Identificación del problema"], "a": 2}, {"q": "¿Para qué sirve la etapa de pruebas?", "o": ["Detectar errores y comprobar que el software funciona correctamente", "Elegir el color del computador", "Convertir el monitor en memoria", "Evitar analizar requisitos"], "a": 0}, {"q": "Después de poner un software en uso, la etapa de mantenimiento permite:", "o": ["Corregir, adaptar y mejorar el sistema", "Eliminar obligatoriamente el sistema", "Convertir software en hardware", "Evitar futuras actualizaciones"], "a": 0}, {"q": "¿Quién creó Python?", "o": ["Bill Gates", "Guido van Rossum", "Steve Jobs", "Dennis Ritchie"], "a": 1}, {"q": "¿En qué institución comenzó el desarrollo de Python?", "o": ["CWI, en los Países Bajos", "NASA, en Estados Unidos", "Universidad de Oxford", "Microsoft"], "a": 0}, {"q": "¿En qué año se publicó por primera vez Python?", "o": ["1980", "1989", "1991", "2008"], "a": 2}, {"q": "¿Cuál característica contribuye a que Python sea apropiado para aprender programación?", "o": ["Su sintaxis clara y legible", "Solo funciona con números binarios", "No permite escribir programas completos", "Necesita modificar físicamente la CPU"], "a": 0}, {"q": "¿Qué componente de la CPU realiza operaciones aritméticas y lógicas?", "o": ["ALU", "SSD", "Monitor", "Teclado"], "a": 0}, {"q": "¿Cuál de los siguientes es un dispositivo de salida?", "o": ["Ratón", "Teclado", "Monitor", "Micrófono"], "a": 2}, {"q": "¿Qué ocurre primero cuando el usuario presiona una tecla?", "o": ["El dispositivo de entrada genera una señal que el sistema interpreta", "La impresora guarda la letra", "El SSD muestra la letra", "La pantalla envía la tecla al teclado"], "a": 0}, {"q": "¿Cuál es la representación binaria del número decimal 5?", "o": ["101", "111", "100", "110"], "a": 0}, {"q": "¿Cuántos estados básicos utiliza el sistema binario?", "o": ["2", "8", "10", "16"], "a": 0}, {"q": "En el modelo Entrada–Proceso–Salida, leer un dato con input() corresponde a:", "o": ["Entrada", "Proceso", "Salida", "Almacenamiento permanente"], "a": 0}, {"q": "En Python, ¿qué función se utiliza normalmente para mostrar información en pantalla?", "o": ["input()", "print()", "type()", "int()"], "a": 1}, {"q": "Si un programa recibe dos números, los suma y muestra el resultado, la suma corresponde a:", "o": ["Entrada", "Proceso", "Salida", "Dispositivo físico"], "a": 1}, {"q": "¿Cuál es una ventaja de diseñar un algoritmo antes de escribir el programa?", "o": ["Permite organizar la solución paso a paso", "Evita completamente las pruebas", "Reemplaza la CPU", "Hace innecesario comprender el problema"], "a": 0}, {"q": "¿Cuál orden representa mejor un proceso básico de solución de problemas en programación?", "o": ["Analizar → diseñar algoritmo → programar → probar", "Programar → ignorar el problema → publicar", "Probar → comprar hardware → analizar", "Imprimir → programar → borrar → analizar"], "a": 0}]'::jsonb
where title='Evaluación 1 - Introducción a la Programación'
  and subject='Programación I';

select id, title, subject, jsonb_array_length(questions) as numero_preguntas
from public.exams
where title='Evaluación 1 - Introducción a la Programación'
  and subject='Programación I';
